-- ============================================================
-- Attacks from every angle. 'block' tests must FAIL to do harm; 'allow' tests are normal use that must keep working.
-- Checks return TRUE when the action took effect.
-- ============================================================
-- (ids are written inline below to keep each test readable)

-- ---------------- VISITOR (not signed in) ----------------
select t.try('visitor','reads e-mails of users', null, $$select string_agg(email, ',') from public.profiles$$, $$select $1 is not null$$);
select t.try('visitor','reads conversations', null, $$select count(*) from public.conversations$$, $$select $1::int > 0$$);
select t.try('visitor','reads messages', null, $$select count(*) from public.messages$$, $$select $1::int > 0$$);
select t.try('visitor','reads contracts', null, $$select count(*) from public.contracts$$, $$select $1::int > 0$$);
select t.try('visitor','reads payout details (IBAN)', null, $$select count(*) from public.payout_details$$, $$select $1::int > 0$$);
select t.try('visitor','reads bad-actor flags', null, $$select count(*) from public.user_flags$$, $$select $1::int > 0$$);
select t.try('visitor','reads identifier fingerprints', null, $$select count(*) from public.user_identifiers$$, $$select $1::int > 0$$);
select t.try('visitor','reads invite codes', null, $$select count(*) from public.invites$$, $$select $1::int > 0$$);
select t.try('visitor','reads private editor profile', null, $$select count(*) from public.editor_profiles where id = '00000000-0000-0000-0000-000000000202'$$, $$select $1::int > 0$$);
select t.try('visitor','reads banned editor profile', null, $$select count(*) from public.editor_profiles where id = '00000000-0000-0000-0000-000000000302'$$, $$select $1::int > 0$$);
select t.try('visitor','reads closed jobs', null, $$select count(*) from public.jobs where status = 'closed'$$, $$select $1::int > 0$$);
select t.try('visitor','posts a job', null, $$with x as (insert into public.jobs (owner, title) values ('00000000-0000-0000-0000-000000000101', 'spam') returning 1) select count(*) from x$$, $$select exists (select 1 from public.jobs where title = 'spam')$$);
select t.try('visitor','writes a review', null, $$with x as (insert into public.reviews (editor, client, stars) values ('00000000-0000-0000-0000-000000000203','00000000-0000-0000-0000-000000000101',1) returning 1) select count(*) from x$$, $$select exists (select 1 from public.reviews where editor = '00000000-0000-0000-0000-000000000203')$$);
select t.try('visitor','edits an editor profile', null, $$with x as (update public.editor_profiles set bio = 'hacked' returning 1) select count(*) from x$$, $$select exists (select 1 from public.editor_profiles where bio = 'hacked')$$);
select t.try('visitor','deletes projects', null, $$with x as (delete from public.projects returning 1) select count(*) from x$$, $$select not exists (select 1 from public.projects)$$);
select t.try('visitor','uploads a file', null, $$with x as (insert into storage.objects (bucket_id, name) values ('portfolio', 'x/evil.html') returning 1) select count(*) from x$$, $$select exists (select 1 from storage.objects where name = 'x/evil.html')$$);
select t.try('visitor','redeems an invite', null, $$select public.redeem_invite('CUV-GOOD-0001')$$, $$select exists (select 1 from public.invites where used_at is not null)$$);
select t.try('visitor','calls admin_list_users', null, $$select count(*) from public.admin_list_users()$$, $$select coalesce($1::int,0) > 0$$);
select t.try('visitor','gets IBAN via payout_info', null, $$select public.payout_info('00000000-0000-0000-0000-000000000201')::text$$, $$select $1 is not null$$);
select t.try('visitor','opens a conversation', null, $$select public.open_conversation('00000000-0000-0000-0000-000000000201')::text$$, $$select $1 is not null$$);
select t.try('visitor','deletes an account (purge_user)', null, $$select public.purge_user('00000000-0000-0000-0000-000000000201')::text$$, $$select not exists (select 1 from public.profiles where id = '00000000-0000-0000-0000-000000000201')$$);
select t.try('visitor','calls record_identifier to frame someone', null, $$select public.record_identifier('00000000-0000-0000-0000-000000000101', 'email', 'b@t.com', 'x')::text$$, $$select exists (select 1 from public.user_flags where user_id = '00000000-0000-0000-0000-000000000101')$$);
select t.try('visitor','calls create_invite', null, $$select public.create_invite('CUV-HACK-0001')$$, $$select $1 is not null$$);
select t.try('visitor','calls contract_event (fake card)', null, $$select public.contract_event((select c from public.contracts c limit 1), 'funded')::text$$, $$select exists (select 1 from public.messages where payload->>'event' = 'funded')$$);
