select t.try('visitor','reads open jobs (normal)', null, $$select count(*) from public.jobs$$, $$select $1::int = 1$$, 'allow');
select t.try('visitor','reads portfolio projects (normal)', null, $$select count(*) from public.projects$$, $$select $1::int = 1$$, 'allow');

