-- helpers that stand in for the payment provider (owner-only, like the Netlify functions with the service key)
create or replace function t.fund(oid uuid) returns void language sql security definer as $$
  update public.contracts set status = 'funded', funded_at = now(), funded_cents = amount_cents, stripe_payment_intent = 'pi_t_' || left(oid::text, 8) where id = oid;
  insert into public.order_payments (order_id, kind, amount_cents, fee_cents, provider, provider_ref) select id, 'fund', amount_cents, 787, 'stripe', 'pi_t' from public.contracts where id = oid;
  insert into public.order_events (order_id, actor, event, data) select id, null, 'funded', jsonb_build_object('amount_cents', amount_cents) from public.contracts where id = oid;
$$;
create or replace function t.release_ms(mid uuid) returns void language sql security definer as $$
  update public.order_milestones set status = 'released', released_at = now(), transfer_ref = 'tr_t' where id = mid;
  update public.contracts c set released_cents = released_cents + m.amount_cents from public.order_milestones m where m.id = mid and c.id = m.order_id;
  insert into public.order_payments (order_id, milestone_id, kind, amount_cents, provider, provider_ref) select order_id, id, 'release', amount_cents, 'stripe', 'tr_t' from public.order_milestones where id = mid;
$$;
create or replace function t.as_user(u text) returns text language sql as $$ select set_config('request.jwt.claim.sub', t.u(u)::text, true) $$;
grant execute on function t.fund(uuid), t.release_ms(uuid), t.as_user(text) to authenticated;

create or replace function t.v18_order(p_price int, p_ms jsonb default null, p_mode text default 'escrow') returns jsonb language sql as $$
  select jsonb_build_object('title', 'Ten-minute YouTube edit', 'scope', 'Edit one 10-minute video, colour, audio', 'deliverables', E'Final 4K MP4\nProject file', 'price_cents', p_price,
                            'deadline', (current_date + 14)::text, 'revisions', 2, 'client_duties', 'Upload raw footage', 'rights', 'full', 'profession_slug', 'video-editor',
                            'mode', p_mode, 'language', 'en', 'law', 'DE', 'milestones', coalesce(p_ms, '[]'::jsonb));
$$;
grant execute on function t.v18_order(int, jsonb, text) to authenticated;

-- flow A: edit before acceptance wipes the earlier acceptance; both must accept the same version
create or replace function t.f_edit_before_accept() returns text language plpgsql as $$
declare oid uuid; c public.contracts%rowtype; out text := '';
begin
  perform t.as_user('102'); oid := public.order_create('10000000-0000-0000-0000-000000000006', t.v18_order(9000));
  select * into c from public.contracts where id = oid;
  out := out || coalesce(c.client_accepted_version::text, '-') || '/' || coalesce(c.freelancer_accepted_version::text, '-') || '/' || c.status;
  perform t.as_user('203'); out := out || '|' || public.order_update(oid, t.v18_order(9500));
  select * into c from public.contracts where id = oid;
  out := out || '|' || coalesce(c.client_accepted_version::text, '-') || '/' || coalesce(c.freelancer_accepted_version::text, '-') || '/' || c.status || '/' || c.terms_version || '/' || c.amount_cents;
  out := out || '|' || public.order_accept(oid);                                     -- the editor accepting his own change again: nothing new
  perform t.as_user('102'); out := out || '|' || public.order_accept(oid);
  select * into c from public.contracts where id = oid;
  out := out || '|' || c.status || '/' || coalesce(c.accepted_version::text, '-') || '/' || (c.client_accepted_at is not null and c.freelancer_accepted_at is not null)::text;
  out := out || '|' || public.order_update(oid, t.v18_order(9900));                  -- accepted: no more silent edits
  out := out || '|' || (select string_agg(event, ',' order by id) from public.order_events where order_id = oid);
  return out;
end $$;
grant execute on function t.f_edit_before_accept() to authenticated;
select t.try('client','edits before acceptance, then both accept the same version (normal)', t.u('102'), $$select t.f_edit_before_accept()$$,
  $$select $1 = '1/-/proposed|ok|-/2/proposed/2/9500|already_accepted|ok|accepted/2/true|not_allowed|created,client_accepted,updated,freelancer_accepted,client_accepted,accepted'$$, 'allow');

-- flow B: a €1,000 milestone Order — partial releases, changes requested, amendment, dispute
create or replace function t.f_milestones() returns text language plpgsql as $$
declare oid uuid; c public.contracts%rowtype; m1 uuid; m2 uuid; aid uuid; out text := ''; ms jsonb;
begin
  ms := '[{"title":"First draft","amount_cents":25000},{"title":"Completed first version","amount_cents":35000},{"title":"Final delivery","amount_cents":40000}]';
  perform t.as_user('206'); oid := public.order_create('10000000-0000-0000-0000-000000000009', t.v18_order(100000, ms));
  perform t.as_user('106'); out := out || public.order_accept(oid);
  perform t.fund(oid);
  select id into m1 from public.order_milestones where order_id = oid and position = 1;
  select id into m2 from public.order_milestones where order_id = oid and position = 2;
  perform t.as_user('106'); out := out || '|' || public.order_milestone_action(m1, 'submit');            -- the client cannot submit work
  perform t.as_user('206'); out := out || '|' || public.order_milestone_action(m1, 'submit', 'first draft is up', 'https://frame.io/x');
  perform t.as_user('106'); out := out || '|' || public.order_milestone_action(m1, 'request_changes', 'make the intro shorter');
  select * into c from public.contracts where id = oid;
  out := out || '|' || (select status from public.order_milestones where id = m1) || '/' || c.changes_used || '/' || c.changes_open::text;
  perform t.as_user('206'); out := out || '|' || public.order_milestone_action(m1, 'submit', 'shorter intro');
  perform t.as_user('106'); out := out || '|' || public.order_milestone_action(m1, 'approve');           -- protected payment: money only moves through the provider
  perform t.release_ms(m1);
  select * into c from public.contracts where id = oid;
  out := out || '|' || c.funded_cents || '/' || c.released_cents || '/' || public.order_held_cents(c);
  -- more work: +€100 as a fourth milestone, proposed by the freelancer, accepted by the client
  perform t.as_user('206'); aid := public.order_amend(oid, '{"note":"Add a 30s teaser","price_delta_cents":10000,"milestones":[{"title":"Teaser","amount_cents":10000}]}');
  out := out || '|' || public.order_amendment_decide(aid, true);                                         -- the proposer cannot accept his own amendment
  perform t.as_user('106'); out := out || '|' || public.order_amendment_decide(aid, true);
  select * into c from public.contracts where id = oid;
  out := out || '|' || c.amount_cents || '/' || c.amendments || '/' || (select count(*) from public.order_milestones where order_id = oid) || '/' || public.order_held_cents(c) || '/' || (c.amount_cents - c.funded_cents);
  -- the client disputes: nothing more is released automatically
  perform t.as_user('206'); out := out || '|' || public.order_milestone_action(m2, 'submit');
  perform t.as_user('106'); out := out || '|' || public.order_action(oid, 'dispute', 'the second part is not what we agreed');
  select * into c from public.contracts where id = oid;
  out := out || '|' || c.status || '/' || (select count(*) from public.order_milestones where order_id = oid and auto_release_at is not null);
  begin perform t.as_user('206'); aid := public.order_amend(oid, '{"note":"pay me more","price_delta_cents":5000}'); out := out || '|amended'; exception when others then out := out || '|' || sqlerrm; end;
  out := out || '|' || (select count(*) from public.order_payments where order_id = oid) || '/' || (select string_agg(event, ',' order by id) from public.order_events where order_id = oid);
  return out;
end $$;
grant execute on function t.f_milestones() to authenticated;
select t.try('client','runs a €1,000 milestone Order: partial release, changes, amendment, dispute (normal)', t.u('106'), $$select t.f_milestones()$$,
  $$select $1 = 'ok|not_allowed|ok|ok|pending/1/true|ok|not_allowed|100000/25000/75000|not_allowed|ok|110000/1/4/75000/10000|ok|ok|disputed/0|not_allowed|2/created,freelancer_accepted,client_accepted,accepted,funded,milestone_submitted,milestone_changes_requested,milestone_submitted,amendment_proposed,amendment_accepted,milestone_submitted,disputed'$$, 'allow');

-- flow C: direct payment (no provider yet): mark paid → confirm → deliver → changes → approve
create or replace function t.f_direct() returns text language plpgsql as $$
declare oid uuid; c public.contracts%rowtype; out text := '';
begin
  perform t.as_user('102'); oid := public.order_create('10000000-0000-0000-0000-000000000006', t.v18_order(9000, null, 'direct'));
  perform t.as_user('203'); out := out || public.order_accept(oid);
  out := out || '|' || public.order_action(oid, 'mark_paid');                                  -- only the client can say they paid
  perform t.as_user('102'); out := out || '|' || public.order_action(oid, 'mark_paid');
  out := out || '|' || public.order_action(oid, 'confirm_paid');                               -- only the freelancer can confirm money arrived
  perform t.as_user('203'); out := out || '|' || public.order_action(oid, 'confirm_paid');
  out := out || '|' || public.order_action(oid, 'deliver', 'done', 'https://example.com/final.mp4');
  perform t.as_user('102'); out := out || '|' || public.order_action(oid, 'request_changes', 'logo is wrong');
  perform t.as_user('203'); out := out || '|' || public.order_action(oid, 'complete');          -- the freelancer cannot approve his own work
  out := out || '|' || public.order_action(oid, 'deliver', 'fixed');
  perform t.as_user('102'); out := out || '|' || public.order_action(oid, 'complete');
  select * into c from public.contracts where id = oid;
  out := out || '|' || c.status || '/' || c.funded_cents || '/' || c.released_cents || '/' || (select string_agg(kind, ',' order by created_at) from public.order_payments where order_id = oid);
  return out;
end $$;
grant execute on function t.f_direct() to authenticated;
select t.try('client','runs a direct-payment Order end to end (normal)', t.u('102'), $$select t.f_direct()$$,
  $$select $1 = 'ok|not_allowed|ok|not_allowed|ok|ok|ok|not_allowed|ok|ok|completed/9000/9000/fund,release'$$, 'allow');

