-- ---------- v20: jobs a freelancer can trust ----------
-- seed: client 102 also has an expired job and one the risk check hid; 501 is a brand-new client with no history
insert into public.jobs (id, owner, title, status, created_at, expires_at) values
 ('60000000-0000-0000-0000-000000000013', t.u('102'), 'Expired job', 'open', now() - interval '40 days', now() - interval '10 days');
insert into public.jobs (id, owner, title, status, hidden_reason) values
 ('60000000-0000-0000-0000-000000000014', t.u('102'), 'Hidden job', 'hidden', 'auto_review');
insert into public.payout_details (id, stripe_account_id, stripe_payouts_enabled) values (t.u('203'), 'acct_1TestAccount203', true) on conflict (id) do update set stripe_payouts_enabled = true;

create or replace function t.v20_job(u text, p_title text, p_desc text default 'Edit a short film', p_budget text default '€300') returns text language plpgsql as $$
declare st text;
begin
  perform t.as_user(u);
  insert into public.jobs (owner, title, description, budget, profession_slug) values (t.u(u), p_title, p_desc, p_budget, 'video-editor') returning status into st;
  return st;
exception when others then return 'error:' || sqlerrm;
end $$;
create or replace function t.v20_many(u text, n int) returns text language plpgsql as $$
declare i int; out text := '';
begin
  for i in 1..n loop out := out || '|' || t.v20_job(u, 'Job number ' || i, 'Different work each time ' || i); end loop;
  return out;
end $$;
create or replace function t.v20_reports() returns text language plpgsql as $$
declare out text := '';
begin
  perform t.as_user('501'); out := out || public.report_job('60000000-0000-0000-0000-000000000001', 'scam', 'asks for telegram');
  perform t.as_user('201'); out := out || '|' || public.report_job('60000000-0000-0000-0000-000000000001', 'fake');
  perform t.as_user('203'); out := out || '|' || public.report_job('60000000-0000-0000-0000-000000000001', 'spam');
  return out;
end $$;
create or replace function t.v20_renew_loop() returns text language plpgsql as $$
declare i int; r text; out text := '';
begin
  perform t.as_user('102');
  for i in 1..13 loop r := public.renew_job('60000000-0000-0000-0000-000000000013'); out := out || r || ','; exit when r <> 'ok'; end loop;
  return out;
end $$;
create or replace function t.v20_require_identity() returns text language plpgsql as $$
begin
  perform t.as_user('401'); perform public.admin_set_setting('posting_rules', public.setting('posting_rules') || '{"require_identity": true}');
  return t.v20_job('501', 'Needs identity');
end $$;
-- these run as the owner of the schema (security definer): the parts a member cannot do, so the flow can be tested end to end
create or replace function t.v20_fill() returns text language plpgsql security definer as $$
declare cid uuid;
begin
  insert into public.contracts (conversation_id, editor, client, proposed_by, title, price, status, job_id, payment_mode, amount_cents)
    values ('10000000-0000-0000-0000-000000000001', t.u('201'), t.u('101'), t.u('101'), 'From the job post', 100, 'accepted', '60000000-0000-0000-0000-000000000001', 'direct', 10000) returning id into cid;
  update public.contracts set status = 'paid' where id = cid;
  return (select status from public.jobs where id = '60000000-0000-0000-0000-000000000001');
end $$;
create or replace function t.v20_expire() returns text language plpgsql security definer as $$
declare n int;
begin
  n := public.expire_jobs();
  return n::text || '/' || (select status from public.jobs where id = '60000000-0000-0000-0000-000000000013');
end $$;
create or replace function t.v20_report_flood() returns text language plpgsql security definer as $$
begin
  insert into public.rate_events (user_id, kind) select t.u('501'), 'job_report' from generate_series(1, 20);
  perform t.as_user('501');
  return public.report_job('60000000-0000-0000-0000-000000000001', 'spam');
end $$;
grant execute on function t.v20_job(text, text, text, text), t.v20_many(text, int), t.v20_reports(), t.v20_renew_loop(), t.v20_require_identity(), t.v20_fill(), t.v20_expire(), t.v20_report_flood() to authenticated;

