select t.try('admin','removes a job with a reason: gone from the feed, the owner sees why (normal)', t.u('401'), $$select public.admin_job_action('60000000-0000-0000-0000-000000000001', 'remove', 'Asks freelancers to pay a fee')$$, $$select $1 = 'ok' and (select status = 'removed' and hidden_reason = 'Asks freelancers to pay a fee' from public.jobs where id = '60000000-0000-0000-0000-000000000001') and not exists (select 1 from public.browse_jobs() b where b.id = '60000000-0000-0000-0000-000000000001')$$, 'allow');
